import{_ as t,o,c,ai as n}from"./chunks/framework.jD4ETUAz.js";const l=JSON.parse('{"title":"安全边界","description":"cninfo-mcp 的安全设计：只访问巨潮资讯网的两个 HTTPS 主机，只在下载目录内写文件，不读取任何凭据，并为每个工具声明只读或写入注解。","frontmatter":{"title":"安全边界","description":"cninfo-mcp 的安全设计：只访问巨潮资讯网的两个 HTTPS 主机，只在下载目录内写文件，不读取任何凭据，并为每个工具声明只读或写入注解。","lastUpdated":"2026-11-15T21:29:49.000Z","upstream":"docs/security.md","head":[["link",{"rel":"canonical","href":"https://youhaozhao.github.io/cninfo-mcp/reference/security"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"cninfo-mcp"}],["meta",{"property":"og:title","content":"安全边界 | cninfo-mcp"}],["meta",{"property":"og:description","content":"cninfo-mcp 的安全设计：只访问巨潮资讯网的两个 HTTPS 主机，只在下载目录内写文件，不读取任何凭据，并为每个工具声明只读或写入注解。"}],["meta",{"property":"og:url","content":"https://youhaozhao.github.io/cninfo-mcp/reference/security"}],["meta",{"property":"og:image","content":"https://youhaozhao.github.io/cninfo-mcp/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"安全边界 | cninfo-mcp"}],["meta",{"name":"twitter:description","content":"cninfo-mcp 的安全设计：只访问巨潮资讯网的两个 HTTPS 主机，只在下载目录内写文件，不读取任何凭据，并为每个工具声明只读或写入注解。"}],["meta",{"name":"twitter:image","content":"https://youhaozhao.github.io/cninfo-mcp/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"首页\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"参考\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/reference/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"安全边界\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/reference/security\\"}]}]}"]]},"headers":[],"relativePath":"reference/security.md","filePath":"reference/security.md","lastUpdated":1794778189000}'),d={name:"reference/security.md"};function a(i,e,r,s,p,m){return o(),c("div",null,[...e[0]||(e[0]=[n('<h1 id="安全边界" tabindex="-1">安全边界 <a class="header-anchor" href="#安全边界" aria-label="Permalink to &quot;安全边界&quot;">​</a></h1><ul><li><strong>网络</strong>：只访问 <code>https://www.cninfo.com.cn</code>（查询与数据）和 <code>https://static.cninfo.com.cn</code>（文档），全程 HTTPS。重定向逐跳校验，不会被带到其他主机。</li><li><strong>文件</strong>：只有两个下载工具会写用户可见的文件，并且只写入下载根目录（<code>CNINFO_MCP_DOWNLOAD_DIR</code>，默认 <code>~/Downloads/cninfo-mcp</code>）。根目录由部署方在客户端配置里指定，工具调用方无法更改。除此之外，服务器只写自己的缓存目录（<code>CNINFO_MCP_CACHE_DIR</code>）。</li><li><strong>写入确认</strong>：服务器自身不弹确认框。下载工具声明了 <code>readOnlyHint: false</code>，是否在调用前向用户确认由 MCP 客户端决定。</li><li><strong>安装</strong>：<code>npm install</code> 阶段不运行任何脚本；服务器启动时不安装任何东西。</li><li><strong>凭据</strong>：不需要、也不读取任何账号、Cookie 或密钥。</li><li><strong>文档内容</strong>：公告和报告是上市公司披露的外部内容，助手应当把它们当作资料而不是指令。</li></ul><h2 id="文档地址" tabindex="-1">文档地址 <a class="header-anchor" href="#文档地址" aria-label="Permalink to &quot;文档地址&quot;">​</a></h2><p><code>read_document</code> 和 <code>download_documents</code> 只接受 <code>https://static.cninfo.com.cn</code> 上的地址（或其 <code>finalpage/...</code> 相对路径），其他主机、非 HTTPS、带账号信息或非默认端口的地址都会被拒绝。</p><h2 id="保存路径" tabindex="-1">保存路径 <a class="header-anchor" href="#保存路径" aria-label="Permalink to &quot;保存路径&quot;">​</a></h2><p><code>download_reports</code> 和 <code>download_documents</code> 的 <code>save_path</code> 只能是下载根目录内的位置：相对路径（如 <code>annual/2024</code>）按根目录下的子目录解析，落在根目录之外的路径（包括 <code>..</code> 和指向外部的符号链接）会被拒绝，不会写入任何文件。</p><h2 id="mcp-工具注解" tabindex="-1">MCP 工具注解 <a class="header-anchor" href="#mcp-工具注解" aria-label="Permalink to &quot;MCP 工具注解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th><code>readOnlyHint</code></th><th><code>destructiveHint</code></th><th><code>idempotentHint</code></th><th><code>openWorldHint</code></th></tr></thead><tbody><tr><td><code>search_securities</code>、<code>list_reports</code>、<code>search_announcements</code>、<code>read_document</code>、<code>get_financials</code>、<code>get_company_data</code></td><td><code>true</code></td><td><code>false</code></td><td><code>true</code></td><td><code>true</code></td></tr><tr><td><code>download_reports</code>、<code>download_documents</code></td><td><code>false</code></td><td><code>false</code></td><td><code>true</code></td><td><code>true</code></td></tr></tbody></table><h2 id="依赖" tabindex="-1">依赖 <a class="header-anchor" href="#依赖" aria-label="Permalink to &quot;依赖&quot;">​</a></h2><p>发布包是自包含的：构建时用 esbuild 把源码和依赖（MCP SDK、zod、pdf.js 等）打进 <code>dist/</code>，安装时不会再拉取任何其他包。被打包的第三方软件及其许可证列在包内的 <code>dist/THIRD-PARTY-LICENSES.txt</code>。</p>',10)])])}const u=t(d,[["render",a]]);export{l as __pageData,u as default};
